-- Zul'Gurub: the Classic armor, jewelry, cloaks, shields and off-hands that drop there had no item row (the WoW
-- Forever client blanks them), so every one was an invalid loot item and nothing dropped. Rows from the Classic
-- item data: stats as budget shares, armor from the item level formula, Classic sell prices, Classic equip
-- spells as item effects, hotfix_data so the client shows them.
DELETE FROM `item_sparse` WHERE `ID` IN (19855,19856,19857,19862,19863,19869,19870,19871,19873,19875,19876,19877,19878,19885,19886,19887,19888,19889,19891,19892,19893,19894,19895,19897,19898,19899,19904,19905,19906,19907,19915,19919,19920,19923,19925,19928,19929,19930,19945,19947,20032,20257,20259,20260,20261,20262,20263,20264,20265,20266,22711,22712,22714,22715,22716,22718,22720,22721,22722);
DELETE FROM `item_effect` WHERE `ID` BETWEEN 9900507 AND 9900585;
DELETE FROM `item_x_item_effect` WHERE `ID` BETWEEN 9900507 AND 9900585;
DELETE FROM `hotfix_data` WHERE `Id` BETWEEN 26112740 AND 26112956;
